<?php
if(!isset($documentType)){http_response_code(404);exit;}
require dirname(__DIR__).'/app/bootstrap.php';$perm=$documentType==='invoice'?'invoices':'quotations';require_permission($perm.'.view');require dirname(__DIR__).'/app/layout.php';
$search=mb_substr(trim($_GET['q']??''),0,100);$page=max(1,(int)($_GET['page']??1));$status=trim($_GET['status']??'');$dates=isset($_GET['period'])?period():null;
$actions=can($perm.'.export')?'<a class="btn" href="export.php?module='.$perm.'">'.icon('download').' Export</a>':'';if(can($perm.'.create'))$actions.='<a class="btn primary" href="'.($documentType==='invoice'?'invoice':'quotation').'-create.php">'.icon('plus').' Create '.$documentType.'</a>';
page_start($documentType==='invoice'?'Billing & Invoices':'Quotations',$documentType==='invoice'?'From work delivered to payments collected. Keep it all connected.':'Make a great first impression. Send a proposal that means business.',$actions);
$count=count_documents($documentType,$search,$dates,$status);$list=list_documents($documentType,$search,15,($page-1)*15,$dates,$status);
?><section class="panel"><form class="list-toolbar"><div class="list-search"><?= icon('search') ?><input type="search" name="q" value="<?= e($search) ?>" placeholder="Search by number or customer..." aria-label="Search documents"></div><select name="status" aria-label="Document status" data-auto-submit><option value="">All statuses</option><?php foreach($documentType==='invoice'?['Draft','Issued','Partially Paid','Paid','Overdue','Void']:['Draft','Sent','Accepted','Declined','Expired'] as $st): ?><option <?= $status===$st?'selected':'' ?>><?= e($st) ?></option><?php endforeach; ?></select><button class="btn"><?= icon('filter') ?> Filter</button></form><div class="table-scroll"><table><thead><tr><th>NUMBER</th><th>CUSTOMER</th><th>DATE</th><th><?= $documentType==='invoice'?'DUE DATE':'VALID UNTIL' ?></th><th>TOTAL</th><th><?= $documentType==='invoice'?'OUTSTANDING':'STATUS' ?></th><th>STATUS</th><th></th></tr></thead><tbody><?php foreach($list as $d): ?><tr><td><a href="invoice-view.php?id=<?= $d['id'] ?>"><strong><?= e($d['number']) ?></strong></a></td><td><div class="cell-person"><span class="avatar blue"><?= e(initials($d['customer_name'])) ?></span><span><?= e($d['customer_name']) ?><small class="sub"><?= e($d['company']) ?></small></span></div></td><td><?= date_label($d['issue_date']) ?></td><td><?= date_label($d['due_date']) ?></td><td><strong><?= money($d['total']) ?></strong></td><td><?= $documentType==='invoice'?money(max(0,(float)$d['total']-(float)$d['paid'])):badge($d['status']) ?></td><td><?= badge(document_status($d)) ?></td><td><a class="btn small" href="invoice-view.php?id=<?= $d['id'] ?>">View <?= icon('arrow-up-right') ?></a></td></tr><?php endforeach;if(!$list): ?><tr><td colspan="8" class="empty"><?= icon('file-invoice') ?><h2>A fresh start for your <?= $perm ?>.</h2><p>Create your first <?= $documentType ?> to see it here.</p></td></tr><?php endif; ?></tbody></table></div><div class="table-foot"><span><?= $count ?> <?= $perm ?> · Page <?= $page ?></span><div class="pagination"><?php if($page>1): ?><a class="btn" href="?<?= e(http_build_query(array_merge($_GET,['page'=>$page-1]))) ?>">Previous</a><?php endif;if($page*15<$count): ?><a class="btn" href="?<?= e(http_build_query(array_merge($_GET,['page'=>$page+1]))) ?>">Next</a><?php endif; ?></div></div></section><?php page_end(); ?>
